query GetUser($id: ID!, $first: Int = 10) { user(id: $id) { id name email
 posts(first: $first, orderBy: {field: CREATED_AT, direction: DESC}) { edges { node { id title tags } } pageInfo { hasNextPage endCursor } }
 ...ProfileFields } }
fragment ProfileFields on User { avatarUrl(size: 128) bio }

"A registered user"
type User implements Node {
  id: ID!
  email: String!
  name: String
  role: Role!
  posts(first: Int = 10): [Post!]!
}

interface Node { id: ID! }

type Post implements Node {
  id: ID!
  title: String!
  tags: [String!]
  author: User!
}

enum Role { ADMIN EDITOR VIEWER }

input CreatePostInput {
  title: String!
  tags: [String!]
}

union SearchResult = User | Post
scalar DateTime

